import os
import json
from pathlib import Path

# Read both policy documents
policy_files = []
for file in os.listdir('.'):
    if file.endswith('.json') and 'policy' in file.lower():
        policy_files.append(file)

print(f"Found policy files: {policy_files}")

policies = {}
for policy_file in policy_files:
    try:
        with open(policy_file, 'r') as f:
            policies[policy_file] = json.load(f)
        print(f"Successfully loaded {policy_file}")
    except Exception as e:
        print(f"Error loading {policy_file}: {e}")

# Analyze policies to determine authoritative one for cumulative case reporting
print("\nAnalyzing policies for cumulative case reporting authority...")

for filename, policy in policies.items():
    print(f"\n--- {filename} ---")

    # Check if this policy addresses cumulative case reporting
    if 'cumulative_case_reporting' in str(policy).lower() or 'reporting' in str(policy).lower():
        print("Contains cumulative case reporting provisions")

    # Check for authority indicators
    authority_indicators = []

    # Look for authority statements
    if isinstance(policy, dict):
        # Check for explicit authority statements
        for key, value in policy.items():
            if 'authority' in str(key).lower() or 'primary' in str(key).lower():
                authority_indicators.append(f"Authority field: {key}")

            # Check if this is specifically about cumulative reporting
            if 'cumulative' in str(key).lower() or 'cumulative' in str(value).lower():
                authority_indicators.append(f"Cumulative reporting mentioned in: {key}")

    # Also check nested structures
    policy_str = json.dumps(policy).lower()
    if 'authoritative' in policy_str or 'primary' in policy_str:
        authority_indicators.append("Contains 'authoritative' or 'primary' designation")

    if authority_indicators:
        print("Authority indicators found:")
        for indicator in authority_indicators:
            print(f"  - {indicator}")
    else:
        print("No clear authority indicators found")

# Determine the authoritative policy
print("\n" + "="*60)
print("DETERMINING AUTHORITATIVE POLICY")
print("="*60)

authoritative_policy = None
reasons = []

for filename, policy in policies.items():
    policy_score = 0
    policy_reasons = []

    # Score based on various factors
    policy_str = json.dumps(policy).lower()

    # Factor 1: Explicit authority statements
    if 'authoritative' in policy_str:
        policy_score += 3
        policy_reasons.append("Explicitly states it is authoritative")

    if 'primary' in policy_str:
        policy_score += 2
        policy_reasons.append("Identified as primary policy")

    # Factor 2: Specificity to cumulative reporting
    if 'cumulative' in policy_str and 'report' in policy_str:
        policy_score += 2
        policy_reasons.append("Specifically addresses cumulative reporting")

    # Factor 3: Comprehensive coverage
    if isinstance(policy, dict) and len(policy) > 5:  # More comprehensive
        policy_score += 1
        policy_reasons.append("Comprehensive policy document")

    # Factor 4: Recent updates (check for dates)
    if 'date' in policy_str or 'version' in policy_str:
        policy_score += 1
        policy_reasons.append("Includes version/date information")

    print(f"\n{filename}: Score = {policy_score}")
    if policy_reasons:
        print("Reasons:", ", ".join(policy_reasons))

    # Update authoritative policy if this has higher score
    if authoritative_policy is None or policy_score > authoritative_policy['score']:
        authoritative_policy = {
            'filename': filename,
            'score': policy_score,
            'reasons': policy_reasons
        }

if authoritative_policy:
    print(f"\n✓ Authoritative policy identified: {authoritative_policy['filename']}")
    print(f"  Score: {authoritative_policy['score']}")
    print(f"  Reasons: {', '.join(authoritative_policy['reasons'])}")

    # Display key sections if available
    print(f"\nKey sections from {authoritative_policy['filename']}:")
    policy_data = policies[authoritative_policy['filename']]

    if isinstance(policy_data, dict):
        for key, value in list(policy_data.items())[:5]:  # Show first 5 items
            if isinstance(value, dict) or isinstance(value, list):
                print(f"  {key}: {type(value).__name__} with {len(value) if hasattr(value, '__len__') else 'N/A'} items")
            else:
                print(f"  {key}: {str(value)[:100]}...")
else:
    print("\n✗ Could not determine authoritative policy from available documents")
